import numpy as np

def problem(x: np.ndarray) -> float:
    x1, x2 = x
    return float(0.92*(x1**2 + x2**2 + 0.6*x1*x2) + 0.01*x1 - 0.02*x2 + 0.07*x1*x2 + 0.0005 * (x1+x2))

import numpy as np

def problem(x: np.ndarray) -> float:
    a = 0.2
    b = 0.6
    c = 0.1
    return a * (x[0]**2 + x[1]**2 + 0.5*x[0]**3 + 0.5*x[1]**3) + b * x[0] * x[1] + c * (x[0] + x[1])

import numpy as np

def problem(x: np.ndarray) -> float:
    x1, x2 = x
    return float(0.92*(x1**2 + x2**2 + 0.6*x1*x2) + 0.01*x1 - 0.02*x2 + 0.07*x1*x2 + 0.0005 * (x1+x2) + 0.1*np.exp(x1 - 2*x2))

import numpy as np

def problem(x: np.ndarray) -> float:
    x1, x2 = x
    return float(x1**2 + x2**2 + 0.2 * x1 * x2)

import numpy as np

