    x1, x2 = x
    return float(0.92*(x1**2 + x2**2 + 0.6*x1*x2) + 0.0005 * (x1+x2))

import numpy as np

def problem(x: np.ndarray) -> float:
    x1, x2 = x
    a = 0.9
    return (x1**2 + x2**2 + a*x1*x2) + 0.05*(x1**3 + x2**3) + np.exp(0.5*x1 + 0.2*x2) + 0.1*np.sin(3*x1 + x2)

import numpy as np

def problem(x: np.ndarray) -> float:
    if len(x) != 2:
        raise ValueError("Input vector must have dimension 2.")

    x1, x2 = x
    return 0.001 * ((x1**2) + (2 * x2**2) + (0.5 * x1 * x2)) * np.exp(0.2 * x1) + 0.0001

import numpy as np

def problem(x: np.ndarray) -> float:
    x1, x2 = x
    a = 0.5
    return (0.9*x1**2 + 1.1*x2**2 + a*x1*x2) + 0.1*np.exp(0.2*x1 + 0.1*x2) * np.sin(4*x1 + 2*x2) + 0.01*np.exp(x1**3 + x2**3)

import numpy as np

def problem(x: np.ndarray) -> float:
    if len(x) != 2:
        raise ValueError("Input vector must have dimension 2.")

    x1, x2 = x

    quadratic_term = (x1**2) + (2 * x2**2) + (0.5 * x1 * x2)
    skew_factor = np.exp(0.2 * x1)

    r = np.sqrt(x1**2 + x2**2)
    rbf_term = 0.1 * np.log(1 + r) * np.exp(-r)

    return  0.001 * (quadratic_term * skew_factor + rbf_term)
